  border-radius: 999px;
  background: var(--panel-3);
  overflow: hidden;
}
.ctx-bar-fill {
  height: 100%;
  border-radius: 999px;
  background: var(--accent);
}
.ctx-bar-fill[data-near="1"] {
  background: var(--warn);
}

/* ---------- context tile bar (Status) ---------- */
