  position: relative;
  height: 4px;
  margin: 6px 0 2px;
  border-radius: 999px;
  background: var(--panel-3);
  overflow: hidden;
}
.ctx-bar::after {
  content: "";
  position: absolute;
  inset: 0;
  width: var(--ctx-pct, 0%);
